UPDATE quiz_questions SET question_ru = 'Где родился Махмуд аз-Замахшари?', options_ru = '["В городе Бухаре", "В хорезмском селении Замахшар", "В городе Самарканде", "В городе Мерве"]'::jsonb, explanation_ru = 'Замахшари родился в 1075 году в хорезмском селении Замахшар, и его нисба «Замахшари» взята от названия этого селения.' WHERE id = 2540;
