UPDATE quiz_questions SET question_ru = 'Какому тарикату в суфизме положил начало Наджмиддин Кубра?', options_ru = '["Накшбандия", "Кубравия", "Яссавия", "Кадирия"]'::jsonb, explanation_ru = 'Наджмиддин Кубра положил начало знаменитому в суфизме тарикату кубравия. Люди этого тариката проповедовали тайный зикр, а учение распространилось главным образом в Средней Азии и отчасти в Иране.' WHERE id = 2546;
