UPDATE quiz_questions SET question_ru = 'Как поступил Наджмиддин Кубра, когда монголы вторглись в Хорезм?', options_ru = '["Переселился с мюридами в другую страну", "Заключил с монголами мир", "Отослал мюридов на родину, а сам выступил на оборону города", "Ушёл прятаться в горы"]'::jsonb, explanation_ru = 'Кубра отослал пришедших из других краёв мюридов на их родину, а сам со словами «Мне не дозволено покидать Хорезм!» выступил на оборону города и принял мученическую смерть.' WHERE id = 2548;

