UPDATE quiz_questions SET question_ru = 'Примерно сколько сатирических произведений создал Мукими?', options_ru = '["Около 10", "Около 20", "Около 30", "Более 50"]'::jsonb, explanation_ru = 'Мукими создал около 30 сатирических произведений — «Танабчилар», «Выборы», «Я безумец», «Я плешивый», «Мухи», — в которых разоблачены проделки царских чиновников и местных богачей.' WHERE id = 2554;

