UPDATE quiz_questions SET question_ru = 'В каком году Уткир Хашимов получил звание «Народный писатель Узбекистана»?', options_ru = '["1986", "1991", "1996", "2001"]'::jsonb, explanation_ru = 'Звание «Народный писатель Узбекистана» было присвоено Уткиру Хашимову в 1991 году. В 1996 году он был награждён орденом «Мехнат шухрати», в 2001 году — орденом «За выдающиеся заслуги».' WHERE id = 2596;
UPDATE quiz_questions SET question_ru = 'Какому тарикату положил начало Абдулхалик Гиждувани?', options_ru = '["Тарикату ходжаган", "Тарикату яссавия", "Тарикату кадирия", "Тарикату кубравия"]'::jsonb, explanation_ru = 'Абдулхалик Гиждувани считается основателем тариката ходжей — ходжаган. Его учение позже распространилось во многих краях как тарикат ходжаган-накшбандия.' WHERE id = 2597;
UPDATE quiz_questions SET question_ru = 'Сколько рашха-правил разработал Абдулхалик Гиждувани в своём тарикате?', options_ru = '["Четыре", "Шесть", "Восемь", "Десять"]'::jsonb, explanation_ru = 'Он разработал восемь рашха-правил тариката: «Хуш дар дам», «Назар бар кадам», «Сафар дар ватан», «Хилват дар анджуман», «Ёдкард», «Бозгашт», «Нигохдошт» и «Ёддошт».' WHERE id = 2598;
UPDATE quiz_questions SET question_ru = 'Какой город Абдуллахан II сделал столицей своего государства?', options_ru = '["Самарканд", "Бухару", "Ташкент", "Балх"]'::jsonb, explanation_ru = 'Абдуллахан II в мае 1557 года овладел Бухарой и сделал её столицей. В его пору Бухара стала средоточием культуры и науки.' WHERE id = 2599;
UPDATE quiz_questions SET question_ru = 'Под каким псевдонимом писал стихи Абдуллахан II?', options_ru = '["Навои", "Бабур", "Хан", "Фуркат"]'::jsonb, explanation_ru = 'Абдуллахан II был одарённым поэтом и писал стихи на узбекском и персидском языках под псевдонимом «Хан».' WHERE id = 2600;
